#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: putting Wave's sync service online (#172).
#
#   bash apps/sync/setup.sh
#
# Runs in Git Bash (Windows) and on Linux. Safe to re-run: each stage checks
# what's already done. The secrets (the Turso token, the database URL) live
# only in this shell's variables: they're piped to curl, node and wrangler,
# never printed and never written to disk. The non-secret values (the web
# client id, the Worker's URL) are kept in apps/sync/.env.setup, which git
# ignores, so a re-run offers them again.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=12

SYNC_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO_DIR=$(cd "$SYNC_DIR/../.." && pwd)
APP_CONFIG="$REPO_DIR/apps/mobile/app.config.ts"
ENV_FILE="$SYNC_DIR/.env.setup"
DB_NAME="wave-sync"
ANDROID_PACKAGE="dev.leoperez.wave"
# SHA-1 of the debug keystore in Expo's Android template. `expo prebuild`
# copies it to apps/mobile/android/app/debug.keystore, and the generated
# build.gradle signs both debug and release builds with it, CI's APK included.
EXPO_DEBUG_SHA1="5E:8F:16:06:2E:A3:CD:2C:4A:0D:54:78:76:BA:A6:F3:8C:AB:F6:25"

cd "$SYNC_DIR"

die() { printf '\n'; warn "$1"; note "Fix that and run the wizard again: bash apps/sync/setup.sh"; exit 1; }
ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
wrangler() { pnpm exec wrangler "$@"; }

# turso_ok URL TOKEN: the database answers a query with this token. The token
# reaches curl on stdin, so it never shows in the process list.
turso_ok() {
  local host="${1#libsql://}" code
  host="${host#https://}"; host="${host%%/*}"
  [[ -n "$host" && -n "$2" ]] || return 1
  code=$(printf 'Authorization: Bearer %s\n' "$2" |
    curl -sS -o /dev/null -w '%{http_code}' --max-time 20 -H @- \
      -H 'Content-Type: application/json' \
      --data '{"requests":[{"type":"execute","stmt":{"sql":"SELECT 1"}},{"type":"close"}]}' \
      "https://$host/v2/pipeline" 2>/dev/null || true)
  [[ "$code" == 200 ]]
}

# status_of METHOD URL [curl args…]: the HTTP status the service answers
# (000 when it can't be reached).
status_of() {
  local method="$1" url="$2"; shift 2
  curl -sS -o /dev/null -w '%{http_code}' --max-time 20 -X "$method" "$@" "$url" 2>/dev/null || true
}

# set_app_extra KEY VALUE: sets `KEY: "…"` in app.config.ts when the file has
# exactly one such line. Running it again writes the same value again.
set_app_extra() {
  local key="$1" value="$2" count
  [[ -f "$APP_CONFIG" ]] || return 1
  count=$(grep -cE "^[[:space:]]*${key}:[[:space:]]*\"[^\"]*\"" "$APP_CONFIG" || true)
  [[ "$count" == 1 ]] || return 1
  sed -i -E "s|^([[:space:]]*${key}:[[:space:]]*)\"[^\"]*\"|\1\"${value}\"|" "$APP_CONFIG"
}

banner "Put Wave's sync service online"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools"
say "Checking what the wizard needs on this machine."
command -v curl >/dev/null 2>&1 || die "curl isn't installed."
command -v node >/dev/null 2>&1 || die "Node isn't installed (Wave needs 22.18 or later)."
node -e 'const [a,b]=process.versions.node.split(".").map(Number);process.exit(a>22||(a===22&&b>=18)?0:1)' ||
  die "Node $(node --version) is too old: Wave needs 22.18 or later."
ok "node $(node --version)"
command -v pnpm >/dev/null 2>&1 || die "pnpm isn't installed (corepack enable, or npm i -g pnpm)."
ok "pnpm $(pnpm --version)"
if [[ ! -e "$SYNC_DIR/node_modules/@libsql/client" || ! -e "$SYNC_DIR/node_modules/.bin/wrangler" ]]; then
  warn "The repo's dependencies (wrangler, @libsql/client) aren't installed."
  confirm "Run pnpm install in $REPO_DIR now?" || die "Run pnpm install at the repo root."
  (cd "$REPO_DIR" && pnpm install) || die "pnpm install failed."
fi
ok "wrangler $(wrangler --version 2>/dev/null | tail -n1)"
if command -v turso >/dev/null 2>&1; then
  USE_TURSO_CLI=1
  ok "turso CLI found: the wizard will drive it"
else
  USE_TURSO_CLI=0
  note "No turso CLI (on Windows it needs WSL): you'll use Turso's dashboard instead."
fi
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Turso: the database"
say "The service keeps every account in one Turso (libSQL) database, $DB_NAME."
if (( USE_TURSO_CLI )); then
  if ! turso db list >/dev/null 2>&1; then
    step "Sign in to Turso: a browser opens (sign up there if you have no account)."
    turso auth login || true
    turso db list >/dev/null 2>&1 || die "The turso CLI still isn't signed in (turso auth login)."
  fi
  ok "signed in to Turso"
  if turso db show "$DB_NAME" >/dev/null 2>&1; then
    ok "database $DB_NAME exists"
  else
    confirm "Create the Turso database $DB_NAME now?" || die "The service needs the database."
    turso db create "$DB_NAME" || die "turso db create failed."
    turso db show "$DB_NAME" >/dev/null 2>&1 || die "turso db show $DB_NAME doesn't find it."
    ok "created database $DB_NAME"
  fi
  TURSO_DATABASE_URL=$(turso db show --url "$DB_NAME" 2>/dev/null | tr -d '[:space:]' || true)
  [[ "$TURSO_DATABASE_URL" == libsql://* ]] || die "turso db show --url didn't give a libsql:// URL."
  ok "got the database URL (kept in memory only)"
else
  open_url "https://app.turso.tech"
  step "Sign in (or sign up), then open Databases."
  step "If there's no database named $DB_NAME, create one with that name (any location near you)."
  step "Open $DB_NAME and copy its URL: it starts with libsql:// and ends with .turso.io."
  for _ in 1 2 3; do
    ask_secret TURSO_DATABASE_URL "Paste the database URL (hidden):"
    TURSO_DATABASE_URL=$(printf '%s' "$TURSO_DATABASE_URL" | tr -d '[:space:]')
    [[ "$TURSO_DATABASE_URL" =~ ^libsql://[A-Za-z0-9.-]+\.turso\.io/?$ ]] && break
    warn "That isn't a libsql://….turso.io URL. Try again."
    TURSO_DATABASE_URL=""
  done
  [[ -n "$TURSO_DATABASE_URL" ]] || die "No database URL."
  ok "got the database URL (kept in memory only)"
fi
pause "Press Enter to continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Turso: a token for the service"
say "The Worker reaches the database with a token. The wizard checks it against"
say "the database and hands it to Cloudflare; it's never shown or saved here."
TURSO_AUTH_TOKEN=""
if (( USE_TURSO_CLI )); then
  TURSO_AUTH_TOKEN=$(turso db tokens create "$DB_NAME" 2>/dev/null | tr -d '[:space:]' || true)
  [[ -n "$TURSO_AUTH_TOKEN" ]] || die "turso db tokens create $DB_NAME failed."
  ok "made a new token for $DB_NAME"
  note "Each run makes a new one; turso db tokens invalidate $DB_NAME revokes them all."
  turso_ok "$TURSO_DATABASE_URL" "$TURSO_AUTH_TOKEN" || die "The database refused the new token."
else
  step "On $DB_NAME's page, create a token with read and write access and no expiry."
  step "Copy it (the dashboard shows it only once)."
  for _ in 1 2 3; do
    ask_secret TURSO_AUTH_TOKEN "Paste the token (hidden):"
    TURSO_AUTH_TOKEN=$(printf '%s' "$TURSO_AUTH_TOKEN" | tr -d '[:space:]')
    turso_ok "$TURSO_DATABASE_URL" "$TURSO_AUTH_TOKEN" && break
    warn "The database refused that token (or the URL is wrong). Try again."
    TURSO_AUTH_TOKEN=""
  done
  [[ -n "$TURSO_AUTH_TOKEN" ]] || die "No working token. Check the URL and the token."
fi
ok "the database answers a query with this token"
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google: project and consent screen"
say "Signing in with Google needs a Google Cloud project with an OAuth consent"
say "screen. Skip whatever is already done."
open_url "https://console.cloud.google.com/projectcreate"
step "Create a project (e.g. \"Wave\"), or pick the one you already use for Wave."
open_url "https://console.cloud.google.com/auth/overview"
step "In Google Auth Platform › Overview (the second tab), press Get started."
step "App name: Wave. Support email: yours. Audience: External. Contact email: yours."
step "Then in Audience, either add every Google account that will sign in to Wave"
step "as a test user, or press Publish app (Wave asks only for email and profile,"
step "so Google doesn't need to review it)."
warn "Check that the project picker at the top shows the same project on every page."
pause "Press Enter once the consent screen is set up"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Google: the web client"
say "The app asks Google for ID tokens for this client, and the service accepts"
say "only tokens issued for it. Its id isn't a secret."
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Web application. Name: Wave sync."
step "Leave the origins and redirect URIs empty, then press Create."
step "Copy the Client ID (it ends in .apps.googleusercontent.com). Wave doesn't use the client secret."
for _ in 1 2 3; do
  ask GOOGLE_CLIENT_ID "Paste the web Client ID:"
  GOOGLE_CLIENT_ID=$(printf '%s' "$GOOGLE_CLIENT_ID" | tr -d '[:space:]')
  [[ "$GOOGLE_CLIENT_ID" =~ ^[0-9]+-[a-z0-9]+\.apps\.googleusercontent\.com$ ]] && break
  warn "That doesn't look like a client id (<digits>-<letters>.apps.googleusercontent.com)."
  GOOGLE_CLIENT_ID=""
done
[[ -n "$GOOGLE_CLIENT_ID" ]] || die "No web client id."
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
pause "Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Google: the Android client"
say "Google signs in only an app whose package and signing certificate match an"
say "Android client in the same project."
KEYTOOL=$(command -v keytool 2>/dev/null || true)
if [[ -z "$KEYTOOL" && -n "${JAVA_HOME:-}" && -x "$JAVA_HOME/bin/keytool" ]]; then KEYTOOL="$JAVA_HOME/bin/keytool"; fi
KEYSTORE="$REPO_DIR/apps/mobile/android/app/debug.keystore"
if [[ -n "$KEYTOOL" && -f "$KEYSTORE" ]]; then
  LOCAL_SHA1=$("$KEYTOOL" -list -v -keystore "$KEYSTORE" -storepass android -alias androiddebugkey 2>/dev/null |
    sed -n 's/^[[:space:]]*SHA1:[[:space:]]*//p' | tr -d '[:space:]' || true)
  if [[ -n "$LOCAL_SHA1" && "$LOCAL_SHA1" != "$EXPO_DEBUG_SHA1" ]]; then
    warn "Your local debug.keystore isn't Expo's: its SHA-1 is $LOCAL_SHA1."
    note "Add a second Android client with it, so your local builds can sign in too."
  fi
fi
say "CI's release APK, your own release builds and the debug builds are all signed"
say "with the debug keystore from Expo's template, so this one SHA-1 covers them all:"
printf '\n    %s%s%s\n\n' "$BOLD" "$EXPO_DEBUG_SHA1" "$RESET"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Android. Name: Wave Android."
step "Package name: $ANDROID_PACKAGE"
step "SHA-1 certificate fingerprint: the one above. Then press Create."
note "Nothing to copy: the app never uses the Android client's id."
note "If Wave is ever signed with a keystore of its own, add an Android client for"
note "that keystore's SHA-1 too."
confirm "Is the Android client created?" || die "Signing in from the phone needs the Android client."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: sign in"
say "The service runs as the Cloudflare Worker wave-sync, deployed with wrangler."
WHOAMI=$(wrangler whoami 2>&1 || true)
if grep -qi "not authenticated" <<<"$WHOAMI"; then
  step "Sign in to Cloudflare: a browser opens (sign up there for a free account if you have none)."
  note "If wrangler can't take input in this window, run the wizard from Windows Terminal."
  wrangler login || true
  WHOAMI=$(wrangler whoami 2>&1 || true)
fi
if grep -qi "not authenticated" <<<"$WHOAMI"; then
  die "wrangler still isn't signed in (pnpm exec wrangler login, in apps/sync)."
fi
printf '%s\n' "$WHOAMI" | grep -iE "logged in|account" | sed 's/^/    /' || true
ok "wrangler is signed in"
note "With more than one account listed, set CLOUDFLARE_ACCOUNT_ID to Wave's and re-run."
pause "Press Enter to continue"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Turso: run the migrations"
say "Creates the service's tables, and on later runs adds whatever new versions need."
say "Migrations that already ran are skipped."
confirm "Run the pending migrations against $DB_NAME?" || die "The service needs its tables."
TURSO_DATABASE_URL="$TURSO_DATABASE_URL" TURSO_AUTH_TOKEN="$TURSO_AUTH_TOKEN" \
  node scripts/migrate.ts || die "The migrations failed."
ok "the database is up to date"
pause "Press Enter to continue"

# ── 9 ─────────────────────────────────────────────────────────────────────
# Deploy before the secrets: `wrangler secret put` needs the Worker to exist.
# Until they're in, the new Worker answers 500, and nothing calls it yet.
stage "Cloudflare: deploy the Worker"
say "Uploads apps/sync as the Worker wave-sync (wrangler.toml holds no secret)."
note "A new Cloudflare account may be asked to pick a workers.dev subdomain: any name works."
confirm "Deploy wave-sync now?" || die "The Worker has to be deployed to go on."
wrangler deploy || die "wrangler deploy failed."
printf '\n'
say "wrangler printed the Worker's address: https://wave-sync.<subdomain>.workers.dev"
for _ in 1 2 3; do
  ask SYNC_URL "Paste the Worker's URL:"
  SYNC_URL=$(printf '%s' "$SYNC_URL" | tr -d '[:space:]')
  SYNC_URL="${SYNC_URL%/}"
  [[ "$SYNC_URL" =~ ^https://[A-Za-z0-9.-]+$ ]] && break
  warn "That isn't an https:// address without a path. Try again."
  SYNC_URL=""
done
[[ -n "$SYNC_URL" ]] || die "No Worker URL."
write_env SYNC_URL "$SYNC_URL"
pause "Press Enter to continue"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: the Worker's secrets"
say "Handing each value to the Worker on stdin; none of them is printed."
put_secret() {
  printf '%s' "$2" | wrangler secret put "$1" >/dev/null || die "wrangler secret put $1 failed."
  ok "set $1"
}
put_secret TURSO_DATABASE_URL "$TURSO_DATABASE_URL"
put_secret TURSO_AUTH_TOKEN "$TURSO_AUTH_TOKEN"
put_secret GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
# SOULSEEK_KEY encrypts the Soulseek accounts the service keeps. It's made
# once, straight into the Worker (no shell variable, no file, never printed),
# and never replaced: accounts kept under an old key can't be read again.
SECRETS=$(wrangler secret list --format json 2>/dev/null) || die "wrangler secret list failed."
if grep -q '"SOULSEEK_KEY"' <<<"$SECRETS"; then
  ok "SOULSEEK_KEY is already set: kept as it is"
else
  node -e "process.stdout.write(require('node:crypto').randomBytes(32).toString('base64'))" |
    wrangler secret put SOULSEEK_KEY >/dev/null || die "wrangler secret put SOULSEEK_KEY failed."
  ok "made SOULSEEK_KEY (32 random bytes) and set it"
  SECRETS=$(wrangler secret list --format json 2>/dev/null) || die "wrangler secret list failed."
fi
for name in TURSO_DATABASE_URL TURSO_AUTH_TOKEN GOOGLE_CLIENT_ID SOULSEEK_KEY; do
  grep -q "\"$name\"" <<<"$SECRETS" || die "wrangler secret list doesn't show $name."
done
ok "wrangler secret list shows all four"
if grep -q '"ALLOWED_EMAILS"' <<<"$SECRETS"; then
  note "ALLOWED_EMAILS is set too: only the emails on it can sign in."
fi
pause "Press Enter to continue"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Check the live service"
say "Asking $SYNC_URL about requests that carry no valid sign-in."
# A new secret can take a few seconds to reach every location: retry a while.
expect_401() {
  local label="$1" code=""
  shift
  for _ in 1 2 3 4 5 6; do
    code=$(status_of "$@")
    if [[ "$code" == 401 ]]; then ok "$label: 401"; return 0; fi
    sleep 5
  done
  warn "$label: expected 401, got ${code:-nothing}."
  return 1
}
FAILED=0
expect_401 "POST /v1/session with a garbage ID token" POST "$SYNC_URL/v1/session" \
  -H 'Content-Type: application/json' --data '{"idToken":"not-a-google-token"}' || FAILED=1
expect_401 "GET /v1/pull without a session" GET "$SYNC_URL/v1/pull" || FAILED=1
# Looking up an unknown session reads the sessions table, so this one also
# proves the database secrets and the migrations.
expect_401 "GET /v1/pull with an unknown session" GET "$SYNC_URL/v1/pull" \
  -H 'Authorization: Bearer not-a-session' || FAILED=1
if (( FAILED )); then
  note "500 means a secret is missing or wrong, or the migrations didn't run;"
  note "pnpm exec wrangler tail (in apps/sync) shows the Worker's errors."
  die "The service doesn't answer as it should."
fi
pause "Press Enter to continue"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "The app's config"
say "The app reads the Worker's URL and the web client id from extra in"
say "apps/mobile/app.config.ts (syncUrl, googleWebClientId). Neither is a secret."
if set_app_extra syncUrl "$SYNC_URL" && set_app_extra googleWebClientId "$GOOGLE_CLIENT_ID"; then
  ok "wrote syncUrl and googleWebClientId in apps/mobile/app.config.ts"
  step "Commit and push it, so the APK CI builds carries them:"
  note "  git add apps/mobile/app.config.ts && git commit -m \"Point the app at the sync service\""
  SKIPPED+=("commit and push apps/mobile/app.config.ts")
else
  warn "app.config.ts has no single syncUrl: \"…\" and googleWebClientId: \"…\" lines to fill."
  step "Set these in extra in apps/mobile/app.config.ts, then commit and push:"
  printf '\n    syncUrl: "%s",\n    googleWebClientId: "%s",\n\n' "$SYNC_URL" "$GOOGLE_CLIENT_ID"
  SKIPPED+=("syncUrl and googleWebClientId in apps/mobile/app.config.ts, committed and pushed")
fi
pause "Press Enter to finish"

finish
say "The sync service is online at $SYNC_URL."
say "Last check, on the phone: install the APK CI builds from that commit, sign in"
say "with Google, and the account starts out empty."
note "Later deploys: pnpm --filter @wave/sync run deploy (see apps/sync/README.md)."
printf '\n'
